// Generated by vibelang from src/TerminalRecording.ts; the migrate flow writes it again with each batch.
/**
 * Reproducible terminal snapshots, asciinema v2 replay and shared GIF conversion.
 * Input and credentials are never captured; callers supply only public screens.
 * The renderer is FFmpeg 7+ with drawtext, fontconfig and palette filters.
 * Uses the library catalog's injected filesystem and process host services.
 * @since 1.0.0
 */
import { Data, Effect, FileSystem, Path } from "effect";
import stringWidth from "string-width";
import { execute } from "./RealCliDriver.js";
/**
 * Invalid evidence or a failed renderer never yields a successful receipt.
 * @category errors
 * @since 1.0.0
 */
export class RecordingError extends Data.TaggedError("RecordingError") {
}
/**
 * Record settled screens. Text frames and replay remain on disk if conversion
 * fails; the manifest is written only after the real GIF renderer succeeds.
 * The destination must be new, so stale evidence cannot pass a later run.
 * @category constructors
 * @since 1.0.0
 */
export const make = (options) => Effect.gen(function* () {
    const columns = options.columns ?? 110;
    const rows = options.rows ?? 40;
    const frameDurationMs = options.frameDurationMs ?? 800;
    const maxFrames = options.maxFrames ?? 64;
    if (!options.title.trim() || frameDurationMs % 10 !== 0 || ![
        [columns, 1, 240],
        [rows, 1, 100],
        [frameDurationMs, 200, 10_000],
        [maxFrames, 1, 256]
    ].every(([value, min, max]) => Number.isSafeInteger(value) && value >= min && value <= max)) {
        return yield* Effect.fail(new RecordingError({ reason: "invalid-options" }));
    }
    const frames = [];
    return {
        capture: (label, screen) => Effect.suspend(() => {
            if (!label.trim() || !screen.trim() || screen.length > columns * rows * 8 ||
                screen.includes(String.fromCharCode(27)) || screen.split(/\r?\n/).length > rows ||
                screen.split(/\r?\n/).some((line) => stringWidth(line) > columns)) {
                return Effect.fail(new RecordingError({ reason: "invalid-frame" }));
            }
            if (frames.length >= maxFrames)
                return Effect.fail(new RecordingError({ reason: "frame-limit" }));
            frames.push({ label, screen });
            return Effect.void;
        }),
        write: (directory) => Effect.gen(function* () {
            if (frames.length === 0)
                return yield* Effect.fail(new RecordingError({ reason: "empty" }));
            // Freeze the timeline before the first asynchronous write.
            const timeline = frames.slice();
            const fs = yield* FileSystem.FileSystem;
            const path = yield* Path.Path;
            yield* fs.makeDirectory(directory, { mode: 0o700 });
            const filters = [];
            const seconds = frameDurationMs / 1000;
            for (const [index, frame] of timeline.entries()) {
                const name = `frame-${String(index).padStart(4, "0")}`;
                yield* fs.writeFileString(path.join(directory, `${name}.txt`), frame.screen, { mode: 0o600 });
                // A multiline drawtext block derives its row stride from every
                // fallback glyph's font metrics. Position each terminal row explicitly
                // so a box-drawing character cannot push the composer off the image.
                for (const [row, line] of frame.screen.split(/\r?\n/).entries()) {
                    if (!line.trim())
                        continue;
                    const textfile = `${name}-row-${String(row).padStart(3, "0")}.txt`;
                    yield* fs.writeFileString(path.join(directory, textfile), line, { mode: 0o600 });
                    filters.push(`drawtext=font=monospace:fontsize=16:fontcolor=0xd6deeb:x=12:y=${12 + row * 19}:expansion=none:textfile=${textfile}:enable='eq(n,${index})'`);
                }
            }
            const cast = [
                JSON.stringify({
                    version: 2,
                    width: columns,
                    height: rows,
                    timestamp: 0,
                    title: options.title,
                    env: { TERM: "xterm-256color" }
                }),
                ...timeline.map((frame, index) => JSON.stringify([
                    index * seconds,
                    "o",
                    "\x1b[2J\x1b[H" + frame.screen.replace(/\r?\n/g, "\r\n")
                ])),
                // Hold the final screen for the same duration in both replay formats.
                JSON.stringify([timeline.length * seconds, "o", ""])
            ].join("\n") + "\n";
            yield* fs.writeFileString(path.join(directory, "terminal.cast"), cast, { mode: 0o600 });
            yield* fs.writeFileString(path.join(directory, "terminal.filter"), filters.join(",") + ",split[a][b];[a]palettegen[p];[b][p]paletteuse", { mode: 0o600 });
            const args = [
                "-hide_banner",
                "-loglevel",
                "error",
                "-nostdin",
                "-n",
                "-threads",
                "1",
                "-f",
                "lavfi",
                "-i",
                `color=c=0x011627:s=${columns * 10 + 24}x${rows * 19 + 24}:r=1000/${frameDurationMs}:d=${timeline.length * seconds}`,
                "-filter_complex_threads",
                "1",
                "-/filter_complex",
                "terminal.filter",
                "-frames:v",
                String(timeline.length),
                "-final_delay",
                String(frameDurationMs / 10),
                "-loop",
                "0",
                "terminal.gif"
            ];
            const result = yield* execute({
                executable: options.renderer ?? "ffmpeg",
                args,
                env: options.env ?? {},
                cwd: directory
            });
            yield* fs.writeFileString(path.join(directory, "renderer.log"), result.stderr, { mode: 0o600 });
            if (result.code !== 0) {
                return yield* Effect.fail(new RecordingError({ reason: "conversion" }));
            }
            const gif = path.join(directory, "terminal.gif");
            const header = yield* fs.readFile(gif);
            if (new TextDecoder().decode(header.slice(0, 6)) !== "GIF89a") {
                return yield* Effect.fail(new RecordingError({ reason: "conversion" }));
            }
            const manifest = {
                version: 1,
                title: options.title,
                columns,
                rows,
                frameDurationMs,
                frames: timeline,
                renderer: { executable: options.renderer ?? "ffmpeg", args }
            };
            yield* fs.writeFileString(path.join(directory, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n", {
                mode: 0o600
            });
            return { gif, cast: path.join(directory, "terminal.cast"), manifest: path.join(directory, "manifest.json") };
        })
    };
});
